function testScope() {
  let localVar = "I am local to testScope";
  console.log("Inside:", globalVar);
  console.log("Inside:", localVar);
}

testScope();
console.log("Outside:", globalVar);
FULL_CODE_END -->

# Lexical Scoping & The Scope Chain ⛓️

JavaScript uses **Lexical Scoping**: an inner function has access to variables declared in its outer parent functions, all the way up to the global scope!

```javascript
const company = "CodeCerebrum";

function outer() {
  const department = "Engineering";

  function inner() {
    const team = "Frontend";
    // Can access all 3 levels:
    console.log(`${company} -> ${department} -> ${team}`);
  }

  inner();
}

outer();
```

